// wl_buffer_desc is the wire description of wl_buffer.
pub const wl_buffer_desc = wayland.IfaceDesc{
	name:     'wl_buffer'
	version:  1
	requests: [
		wayland.MsgDesc{
			name:       'destroy'
			opcode:     0
			destructor: true
		},
	]
	events:   [
		wayland.MsgDesc{
			name:   'release'
			opcode: 0
		},
	]
}

// WlBuffer is a client side proxy for wl_buffer. A buffer provides the content for a wl_surface.
pub struct WlBuffer {
	wayland.Object
}

// wl_buffer_proxy wraps an object id in a WlBuffer proxy.
pub fn wl_buffer_proxy(conn &wayland.Connection, id u32) WlBuffer {
	return WlBuffer{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_buffer'
		}
	}
}

// WlBufferListener receives the events of a wl_buffer object.
pub interface WlBufferListener {
	// Sent when this wl_buffer is no longer used by the compositor.
mut:
	release(proxy WlBuffer)
}

// NoopWlBufferListener ignores every wl_buffer event. It is the default listener, so
// objects without a listener never fail on incoming events.
pub struct NoopWlBufferListener {}

pub fn (mut listener NoopWlBufferListener) release(_proxy WlBuffer) {
}

struct WlBufferSink {
mut:
	proxy    WlBuffer
	listener WlBufferListener = NoopWlBufferListener{}
}

fn (mut s WlBufferSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			s.listener.release(s.proxy)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives wl_buffer events.
pub fn (proxy &WlBuffer) set_listener(listener WlBufferListener) ! {
	proxy.conn.set_sink(proxy.id, WlBufferSink{
		proxy:    *proxy
		listener: listener
	})!
}

// Destroy a buffer. If and how you need to release the backing storage is defined by the buffer factory interfac...
pub fn (proxy &WlBuffer) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

