	// Request for data from the client.
	send(proxy WlDataSource, mime_type string, fd int)
	// This data source is no longer valid.
	cancelled(proxy WlDataSource)
	// The user performed the drop action.
	dnd_drop_performed(proxy WlDataSource)
	// The drop destination finished interoperating with this data source, so the client is now free to destroy this ...
	dnd_finished(proxy WlDataSource)
	// This event indicates the action selected by the compositor after matching the source/destination side actions.
	action(proxy WlDataSource, dnd_action u32)
