mut:
	proxy    WlDataSource
	listener WlDataSourceListener = NoopWlDataSourceListener{}
}

fn (mut s WlDataSourceSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			mime_type := msg.arg_string(0)!
			s.listener.target(s.proxy, mime_type)
		}
		1 {
			mime_type := msg.arg_string(0)!
			fd := msg.arg_fd(1)!
			s.listener.send(s.proxy, mime_type, fd)
		}
		2 {
			s.listener.cancelled(s.proxy)
		}
		3 {
			s.listener.dnd_drop_performed(s.proxy)
		}
		4 {
			s.listener.dnd_finished(s.proxy)
		}
		5 {
			dnd_action := msg.arg_u32(0)!
			s.listener.action(s.proxy, dnd_action)
		}
		else {
			return false
		}
	}
	return true
}

