// WlDataDeviceListener receives the events of a wl_data_device object.
pub interface WlDataDeviceListener {
	// The data_offer event introduces a new wl_data_offer object, which will subsequently be used in either the data...
mut:
	data_offer(proxy WlDataDevice, id WlDataOffer)
	// This event is sent when an active drag-and-drop pointer enters a surface owned by the client.
	enter(proxy WlDataDevice, serial u32, surface WlSurface, x f64, y f64, id ?WlDataOffer)
	// This event is sent when the drag-and-drop pointer leaves the surface and the session ends.
	leave(proxy WlDataDevice)
	// This event is sent when the drag-and-drop pointer moves within the currently focused surface.
	motion(proxy WlDataDevice, time u32, x f64, y f64)
	// The event is sent when a drag-and-drop operation is ended because the implicit grab is removed.
	drop(proxy WlDataDevice)
	// The selection event is sent out to notify the client of a new wl_data_offer for the selection for this device.
	selection(proxy WlDataDevice, id ?WlDataOffer)
}

