struct WlDataDeviceSink {
mut:
	proxy    WlDataDevice
	listener WlDataDeviceListener = NoopWlDataDeviceListener{}
}

fn (mut s WlDataDeviceSink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			id_id := msg.arg_id(0)!
			s.proxy.conn.register_object(id_id, 'wl_data_offer', &wl_data_offer_desc)!
			id := wl_data_offer_proxy(s.proxy.conn, id_id)
			s.listener.data_offer(s.proxy, id)
		}
		1 {
			serial := msg.arg_u32(0)!
			surface_id := msg.arg_id(1)!
			surface := wl_surface_proxy(s.proxy.conn, surface_id)
			x := msg.arg_fixed(2)!
			y := msg.arg_fixed(3)!
			id_id := msg.arg_id(4)!
			mut id := ?WlDataOffer(none)
			if id_id != 0 {
				id = wl_data_offer_proxy(s.proxy.conn, id_id)
			}
			s.listener.enter(s.proxy, serial, surface, x, y, id)
		}
		2 {
			s.listener.leave(s.proxy)
		}
		3 {
			time := msg.arg_u32(0)!
			x := msg.arg_fixed(1)!
			y := msg.arg_fixed(2)!
			s.listener.motion(s.proxy, time, x, y)
		}
		4 {
			s.listener.drop(s.proxy)
		}
		5 {
			id_id := msg.arg_id(0)!
			mut id := ?WlDataOffer(none)
			if id_id != 0 {
				id = wl_data_offer_proxy(s.proxy.conn, id_id)
			}
			s.listener.selection(s.proxy, id)
		}
		else {
			return false
		}
	}
	return true
}

