// This request asks the compositor to start a drag-and-drop operation on behalf of the client.
pub fn (proxy &WlDataDevice) start_drag(source ?WlDataSource, origin WlSurface, icon ?WlSurface, serial u32) ! {
	source_id := if value := source { value.id } else { u32(0) }
	icon_id := if value := icon { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 0, [
		wayland.ArgValue(wayland.ObjectRef{ id: source_id }),
		wayland.ArgValue(wayland.ObjectRef{ id: origin.id }),
		wayland.ArgValue(wayland.ObjectRef{ id: icon_id }),
		wayland.ArgValue(serial),
	])!
}

// This request asks the compositor to set the selection to the data from the source on behalf of the client.
pub fn (proxy &WlDataDevice) set_selection(source ?WlDataSource, serial u32) ! {
	source_id := if value := source { value.id } else { u32(0) }
	proxy.conn.request(proxy.id, 1, [
		wayland.ArgValue(wayland.ObjectRef{ id: source_id }),
		wayland.ArgValue(serial),
	])!
}

// This request destroys the data device.
pub fn (proxy &WlDataDevice) release() ! {
	proxy.conn.request(proxy.id, 2, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

