	motion(proxy WlPointer, time u32, surface_x f64, surface_y f64)
	// Mouse button click and release notifications.
	button(proxy WlPointer, serial u32, time u32, button u32, state u32)
	// Scroll and other axis notifications.
	axis(proxy WlPointer, time u32, axis u32, value_ f64)
	// Indicates the end of a set of events that logically belong together.
	frame(proxy WlPointer)
	// Source information for scroll and other axes.
	axis_source(proxy WlPointer, axis_source u32)
	// Stop notification for scroll and other axes.
	axis_stop(proxy WlPointer, time u32, axis u32)
	// Discrete step information for scroll and other axes.
	axis_discrete(proxy WlPointer, axis u32, discrete i32)
	// Discrete high-resolution scroll information.
	axis_value120(proxy WlPointer, axis u32, value120 i32)
	// Relative directional information of the entity causing the axis motion.
	axis_relative_direction(proxy WlPointer, axis u32, direction u32)
	// Notification of pointer location change within a surface.
	warp(proxy WlPointer, surface_x f64, surface_y f64)
}

