}

// wl_region_proxy wraps an object id in a WlRegion proxy.
pub fn wl_region_proxy(conn &wayland.Connection, id u32) WlRegion {
	return WlRegion{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_region'
		}
	}
}

// Destroy the region. This will invalidate the object ID.
pub fn (proxy &WlRegion) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// Add the specified rectangle to the region.
pub fn (proxy &WlRegion) add(x i32, y i32, width i32, height i32) ! {
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(x), wayland.ArgValue(y), wayland.ArgValue(width),
		wayland.ArgValue(height)])!
}

// Subtract the specified rectangle from the region.
pub fn (proxy &WlRegion) subtract(x i32, y i32, width i32, height i32) ! {
	proxy.conn.request(proxy.id, 2, [wayland.ArgValue(x), wayland.ArgValue(y), wayland.ArgValue(width),
		wayland.ArgValue(height)])!
}

