// WlSubcompositor is a client side proxy for wl_subcompositor. The global interface exposing sub-surface compositing capabilities.
pub struct WlSubcompositor {
	wayland.Object
}

// wl_subcompositor_proxy wraps an object id in a WlSubcompositor proxy.
pub fn wl_subcompositor_proxy(conn &wayland.Connection, id u32) WlSubcompositor {
	return WlSubcompositor{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_subcompositor'
		}
	}
}

// Informs the server that the client will not be using this protocol object anymore.
pub fn (proxy &WlSubcompositor) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// Create a sub-surface interface for the given surface, and associate it with the given parent surface.
pub fn (proxy &WlSubcompositor) get_subsurface(surface WlSurface, parent WlSurface) !WlSubsurface {
	id_id := proxy.conn.alloc_id()!
	id_object := wayland.Object{
		id:    id_id
		conn:  proxy.conn
		iface: 'wl_subsurface'
	}
	proxy.conn.register_object(id_id, 'wl_subsurface', &wl_subsurface_desc)!
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(wayland.ObjectRef{ id: id_id }),
		wayland.ArgValue(wayland.ObjectRef{ id: surface.id }),
		wayland.ArgValue(wayland.ObjectRef{ id: parent.id })])!
	return WlSubsurface{
		Object: id_object
	}
}

