// WlSubsurface is a client side proxy for wl_subsurface. An additional interface to a wl_surface object, which has been made a sub-surface.
pub struct WlSubsurface {
	wayland.Object
}

// wl_subsurface_proxy wraps an object id in a WlSubsurface proxy.
pub fn wl_subsurface_proxy(conn &wayland.Connection, id u32) WlSubsurface {
	return WlSubsurface{
		Object: wayland.Object{
			id:    id
			conn:  conn
			iface: 'wl_subsurface'
		}
	}
}

// The sub-surface interface is removed from the wl_surface object that was turned into a sub-surface with a wl_s...
pub fn (proxy &WlSubsurface) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// This sets the position of the sub-surface, relative to the parent surface.
pub fn (proxy &WlSubsurface) set_position(x i32, y i32) ! {
	proxy.conn.request(proxy.id, 1, [wayland.ArgValue(x), wayland.ArgValue(y)])!
}

// This sub-surface is taken from the stack, and put back just above the reference surface, changing the z-order ...
pub fn (proxy &WlSubsurface) place_above(sibling WlSurface) ! {
	proxy.conn.request(proxy.id, 2, [wayland.ArgValue(wayland.ObjectRef{ id: sibling.id })])!
}

// The sub-surface is placed just below the reference surface.
pub fn (proxy &WlSubsurface) place_below(sibling WlSurface) ! {
	proxy.conn.request(proxy.id, 3, [wayland.ArgValue(wayland.ObjectRef{ id: sibling.id })])!
}

// Change the commit behaviour of the sub-surface to synchronized mode.
pub fn (proxy &WlSubsurface) set_sync() ! {
	proxy.conn.request(proxy.id, 4, []wayland.ArgValue{})!
}

// Change the commit behaviour of the sub-surface to desynchronized mode.
pub fn (proxy &WlSubsurface) set_desync() ! {
	proxy.conn.request(proxy.id, 5, []wayland.ArgValue{})!
}

