// bind_wl_compositor binds the wl_compositor global to a typed proxy.
pub fn bind_wl_compositor(conn &wayland.Connection, global wayland.Global) !WlCompositor {
	version := if global.version < wl_compositor_desc.version {
		global.version
	} else {
		wl_compositor_desc.version
	}
	object := conn.bind_global(global, 'wl_compositor', version, &wl_compositor_desc)!
	return WlCompositor{
		Object: object
	}
}

